command:
$ErrorActionPreference = "Stop"
git fetch origin main work/large-folder-5000 --no-tags
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git status --short).Count -ne 0) { throw "dirty checkout" }
if ((git rev-parse origin/main).Trim() -ne "a447073696959ac4460e28603f664aa953c403f1") { throw "main moved" }
git checkout work/large-folder-5000
if ($LASTEXITCODE -ne 0) { throw "checkout failed" }
git merge --ff-only origin/work/large-folder-5000
if ($LASTEXITCODE -ne 0) { throw "branch update failed" }
cmd /c test.bat policy
if ($LASTEXITCODE -ne 0) { throw "policy failed" }
python -X utf8 -m unittest tests.winui.test_large_folder_contract
if ($LASTEXITCODE -ne 0) { throw "contract failed" }
if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "Release binary missing" }
python -X utf8 tests\winui\test_large_owned_folder_gui.py --items 5000 --configuration Release
if ($LASTEXITCODE -ne 0) { throw "5000 GUI failed" }
git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }
Write-Host "LARGE_FOLDER_5000_ACCEPTANCE_PASS"
